tasks.check:
set -o pipefail
[ -e .venv ] || ln -s /home/bcorfman/dev/freytag-forge/.venv .venv
export PYTHONPATH=$PWD TMPDIR=/tmp
PY=.venv/bin/python
CH=$(git status --porcelain | grep -v '^?? .venv' | awk '{print $NF}' | sort | tr '\n' ' ')
[ -n "$CH" ] || { echo "WHY: nothing changed"; exit 1; }
for f in $CH; do case "$f" in storygame/story_package/models.py|storygame/story_package/loader.py|storygame/runtime/cloudflare.py|storygame/audit.py|tests/fixtures/stories/lighthouse-incident/*|tests/test_incident_loader.py|tests/test_incident_engine.py|tests/test_incident_recovery.py|tests/test_lighthouse_ending.py) ;; *) echo "WHY: edited file outside ownership: $f"; exit 1;; esac; done
[ -f tests/test_lighthouse_ending.py ] || { echo "WHY: tests/test_lighthouse_ending.py missing"; exit 1; }
grep -n "successor_transition_id" storygame/story_package/models.py | grep -q "None" || { echo "WHY: successor_transition_id not optional in models.py"; exit 1; }
grep -rniE "lighthouse|continuity|kristin" storygame/story_package/models.py storygame/story_package/loader.py && { echo "WHY: story-specific id added to the engine"; exit 1; }
$PY -m ruff format --check storygame tests/test_lighthouse_ending.py tests/test_incident_loader.py tests/test_incident_engine.py tests/test_incident_recovery.py || { echo "WHY: not ruff-formatted"; exit 1; }
$PY -m ruff check storygame tests/test_lighthouse_ending.py tests/test_incident_loader.py tests/test_incident_engine.py tests/test_incident_recovery.py || { echo "WHY: ruff check failed"; exit 1; }
SUITES=""; for t in test_incident_loader test_incident_engine test_incident_recovery test_lighthouse_ending test_world_second_package test_entry_variants test_story_ending test_3c_cue_chain test_markdown_story_package test_package_audit test_scene_relative_pacing test_cloudflare_provider test_incident_handoff_guard test_scene_roleplay_contract test_loader_pacing_producers; do [ -f tests/$t.py ] && SUITES="$SUITES tests/$t.py"; done
$PY -m pytest -q -p no:cacheprovider $SUITES || { echo "WHY: suites failed"; exit 1; }
OUT=/home/bcorfman/dev/ringer-work/phase2-portability
mkdir -p $OUT && git add -A -- storygame tests && git diff --cached > $OUT/c1c2.patch && wc -l $OUT/c1c2.patch && git diff --cached --stat | tail -12
